package org.brightstats.stats;

import java.util.*;

/** Linear composite IPMA with explicit indicator coding/ranges and effect units. */
public final class ImportancePerformance {
    private ImportancePerformance(){}
    public enum Depth {ALL_PREDECESSORS,DIRECT_PREDECESSORS;@Override public String toString(){return this==ALL_PREDECESSORS?"All direct and indirect predecessors":"Direct predecessors only";}}
    public enum Units {ORIGINAL_UNITS,STANDARDIZED;@Override public String toString(){return this==ORIGINAL_UNITS?"Original construct units":"Standardized score units";}}
    public record Range(int column,double minimum,double maximum,boolean reverse){
        public Range{if(column<0||!Double.isFinite(minimum)||!Double.isFinite(maximum)||!(maximum>minimum)||!Double.isFinite(maximum-minimum))throw new IllegalArgumentException("IPMA ranges require a column and finite increasing bounds.");}
    }
    public record Options(int target,Depth depth,Units units,List<Range> ranges){
        public Options{Objects.requireNonNull(depth);Objects.requireNonNull(units);ranges=List.copyOf(ranges);if(target<0)throw new IllegalArgumentException("Choose an IPMA target.");Set<Integer> columns=new HashSet<>();for(var range:ranges)if(!columns.add(range.column()))throw new IllegalArgumentException("Duplicate IPMA range column.");}
        public static Options defaults(int target){return new Options(target,Depth.ALL_PREDECESSORS,Units.ORIGINAL_UNITS,List.of());}
    }
    public record Construct(int index,String name,double importance,double performance){}
    public record Indicator(int column,String name,double importance,double performance){}
    public record Result(Options options,PlsSem.Options modelOptions,PlsSem.Fit model,List<Range> resolvedRanges,List<Construct> constructs,List<Indicator> indicators,double[] constructPerformance,double[] indicatorPerformance,double[][] rescaledWeights,double[][] rawConstructScores,double[][] performanceScores,double[][] indicatorScores,double[][] paths,double[][] totalEffects,double[][] indicatorEffects,List<String> warnings){
        public Result{resolvedRanges=List.copyOf(resolvedRanges);constructs=List.copyOf(constructs);indicators=List.copyOf(indicators);constructPerformance=constructPerformance.clone();indicatorPerformance=indicatorPerformance.clone();rescaledWeights=Matrices.copy(rescaledWeights);rawConstructScores=Matrices.copy(rawConstructScores);performanceScores=Matrices.copy(performanceScores);indicatorScores=Matrices.copy(indicatorScores);paths=Matrices.copy(paths);totalEffects=Matrices.copy(totalEffects);indicatorEffects=Matrices.copy(indicatorEffects);warnings=List.copyOf(warnings);}
        @Override public double[] constructPerformance(){return constructPerformance.clone();}@Override public double[] indicatorPerformance(){return indicatorPerformance.clone();}@Override public double[][] rescaledWeights(){return Matrices.copy(rescaledWeights);}@Override public double[][] rawConstructScores(){return Matrices.copy(rawConstructScores);}@Override public double[][] performanceScores(){return Matrices.copy(performanceScores);}@Override public double[][] indicatorScores(){return Matrices.copy(indicatorScores);}@Override public double[][] paths(){return Matrices.copy(paths);}@Override public double[][] totalEffects(){return Matrices.copy(totalEffects);}@Override public double[][] indicatorEffects(){return Matrices.copy(indicatorEffects);}
    }
    public static Result fit(double[][] observations,List<String> names,List<PlsSem.Block> suppliedBlocks,List<PlsSem.Edge> suppliedEdges,PlsSem.Options modelOptions,Options options){
        int p=Matrices.width(observations,3),n=observations.length;List<PlsSem.Block> blocks=List.copyOf(suppliedBlocks);List<PlsSem.Edge> edges=List.copyOf(suppliedEdges);int k=blocks.size();if(names.size()!=p||new HashSet<>(names).size()!=p||names.stream().anyMatch(v->v==null||v.isBlank())||options.target()>=k)throw new IllegalArgumentException("IPMA names or target differ from the model.");if((long)n*(p+2L*k)>20000000L||(long)k*(p+(long)k)>10000000L)throw new IllegalArgumentException("IPMA retained-score size exceeds the current limit.");Set<String> blockNames=new HashSet<>();boolean[] used=new boolean[p];for(var block:blocks){if(block.name().isBlank()||!blockNames.add(block.name()))throw new IllegalArgumentException("IPMA construct names must be distinct and nonblank.");for(int column:block.columns()){if(column<0||column>=p)throw new IllegalArgumentException("Invalid IPMA indicator column.");used[column]=true;}}
        Map<Integer,Range> ranges=new HashMap<>();for(var range:options.ranges()){if(range.column()>=p||!used[range.column()])throw new IllegalArgumentException("IPMA range refers to an unused/unavailable indicator.");ranges.put(range.column(),range);}List<Range> resolved=new ArrayList<>();List<String> warnings=new ArrayList<>();double[][] data=Matrices.copy(observations),scaled=new double[n][p];for(double[] row:scaled)Arrays.fill(row,Double.NaN);double[] sd=new double[p],indicatorPerformance=new double[p];Arrays.fill(indicatorPerformance,Double.NaN);boolean empirical=false;
        for(int column=0;column<p;column++)if(used[column]){
            Matrices.interrupted();double minimum=Double.POSITIVE_INFINITY,maximum=Double.NEGATIVE_INFINITY;for(double[] row:observations){minimum=Math.min(minimum,row[column]);maximum=Math.max(maximum,row[column]);}Range range=ranges.get(column);if(range==null){range=new Range(column,minimum,maximum,false);empirical=true;}if(minimum<range.minimum()||maximum>range.maximum())throw new IllegalArgumentException("Observed IPMA values lie outside the declared range: "+names.get(column));resolved.add(range);double mean=0,performance=0;for(int i=0;i<n;i++){if(range.reverse())data[i][column]=range.maximum()-(observations[i][column]-range.minimum());scaled[i][column]=100*((data[i][column]-range.minimum())/(range.maximum()-range.minimum()));mean+=(data[i][column]-mean)/(i+1);performance+=(scaled[i][column]-performance)/(i+1);}double variance=0;for(double[] row:data)variance+=Math.pow(row[column]-mean,2)/n;sd[column]=Math.sqrt(variance);if(!(sd[column]>0)||!Double.isFinite(sd[column])||!Double.isFinite(performance))throw new IllegalArgumentException("Constant or unscalable IPMA indicator: "+names.get(column));indicatorPerformance[column]=performance;
        }
        if(empirical)warnings.add("Some ranges use observed extrema. Confirm theoretical scale bounds before interpreting performance; observed extrema need not be the possible endpoints.");
        var model=PlsSem.fit(data,blocks,edges,modelOptions);if(!model.converged())throw new IllegalArgumentException("IPMA requires a converged PLS model.");double[][] weights=model.weights(),normalized=new double[k][],rawScores=new double[n][k],scores=new double[n][k];double[] sums=new double[k],performances=new double[k];
        for(int j=0;j<k;j++){
            Matrices.interrupted();int[] columns=blocks.get(j).columns();normalized[j]=new double[columns.length];double sum=0;for(int a=0;a<columns.length;a++){normalized[j][a]=weights[j][a]/sd[columns[a]];sum+=normalized[j][a];}if(sum==0||!Double.isFinite(sum)||!Double.isFinite(1/sum))throw new IllegalArgumentException("IPMA weights cannot be normalized: "+blocks.get(j).name());sums[j]=sum;for(int a=0;a<columns.length;a++){normalized[j][a]/=sum;if(!Double.isFinite(normalized[j][a])||normalized[j][a]<0)throw new IllegalArgumentException("IPMA needs consistently oriented, nonnegative normalized weights; review indicator coding for "+blocks.get(j).name());}
            for(int i=0;i<n;i++){for(int a=0;a<columns.length;a++){rawScores[i][j]+=normalized[j][a]*data[i][columns[a]];scores[i][j]+=normalized[j][a]*scaled[i][columns[a]];}if(!Double.isFinite(rawScores[i][j])||!Double.isFinite(scores[i][j]))throw new IllegalArgumentException("IPMA score exceeded finite range.");performances[j]+=(scores[i][j]-performances[j])/(i+1);}
        }
        double[][] paths=new double[k][k],fittedPaths=model.pathCoefficients();for(var edge:edges)paths[edge.source()][edge.target()]=fittedPaths[edge.source()][edge.target()];if(options.units()==Units.ORIGINAL_UNITS)for(var edge:edges)paths[edge.source()][edge.target()]*=sums[edge.source()]/sums[edge.target()];double[][] total=effects(paths,edges);double[][] indicatorEffects=new double[p][k];for(int column=0;column<p;column++)if(!used[column])Arrays.fill(indicatorEffects[column],Double.NaN);for(int j=0;j<k;j++){int[] columns=blocks.get(j).columns();for(int a=0;a<columns.length;a++)for(int target=0;target<k;target++)indicatorEffects[columns[a]][target]+=(options.units()==Units.ORIGINAL_UNITS?normalized[j][a]:weights[j][a])*(total[j][target]+(j==target?1:0));}
        boolean[] included=new boolean[k];if(options.depth()==Depth.DIRECT_PREDECESSORS){for(var edge:edges)if(edge.target()==options.target())included[edge.source()]=true;}else{included[options.target()]=true;for(int pass=0;pass<k;pass++)for(var edge:edges)if(included[edge.target()])included[edge.source()]=true;included[options.target()]=false;}List<Construct> constructs=new ArrayList<>();TreeSet<Integer> indicatorColumns=new TreeSet<>();for(int j=0;j<k;j++)if(included[j]){constructs.add(new Construct(j,blocks.get(j).name(),total[j][options.target()],performances[j]));for(int column:blocks.get(j).columns())indicatorColumns.add(column);}if(constructs.isEmpty())throw new IllegalArgumentException("Choose an IPMA target with predecessor constructs.");constructs.sort(Comparator.comparing(Construct::name));List<Indicator> indicators=indicatorColumns.stream().map(column->new Indicator(column,names.get(column),indicatorEffects[column][options.target()],indicatorPerformance[column])).sorted(Comparator.comparing(Indicator::name)).toList();
        if(constructs.stream().anyMatch(v->v.importance()<0)||indicators.stream().anyMatch(v->v.importance()<0))warnings.add("Negative importance has the opposite directional interpretation; do not rank it as a positive improvement priority.");warnings.add("Performance uses normalized unstandardized weights and 0–100 indicator scores. Importance units are "+options.units()+". Original-unit importance is per unit of the raw weighted construct, not automatically per performance point when indicator ranges differ.");warnings.add("Reverse coding is applied before model estimation. Indicator importance sums all assigned composite routes, including target identity where applicable. These are fitted-model derivatives, not causal guarantees or significance tests.");return new Result(options,modelOptions,model,resolved,constructs,indicators,performances,indicatorPerformance,normalized,rawScores,scores,scaled,paths,total,indicatorEffects,warnings);
    }
    private static double[][] effects(double[][] paths,List<PlsSem.Edge> edges){int k=paths.length;int[] indegree=new int[k];List<List<Integer>> children=new ArrayList<>();for(int j=0;j<k;j++)children.add(new ArrayList<>());for(var edge:edges){indegree[edge.target()]++;children.get(edge.source()).add(edge.target());}List<Integer> order=new ArrayList<>();for(int j=0;j<k;j++)if(indegree[j]==0)order.add(j);for(int q=0;q<order.size();q++)for(int child:children.get(order.get(q)))if(--indegree[child]==0)order.add(child);if(order.size()!=k)throw new IllegalArgumentException("IPMA requires an acyclic structural model.");double[][] total=new double[k][k];for(int j=0;j<k;j++)total[j][j]=1;for(int parent:order){Matrices.interrupted();for(int child:children.get(parent))for(int source=0;source<k;source++){total[source][child]+=total[source][parent]*paths[parent][child];if(!Double.isFinite(total[source][child]))throw new IllegalArgumentException("IPMA total effect exceeded finite range.");}}for(int j=0;j<k;j++)total[j][j]=0;return total;}
}
